    const r = 2; // m, length of the pendulum
    const g = 9.81; // m/s^2, acceleration due to gravity

    // Initial tension at theta = 0
    const theta0 = 0; // degrees
    const T0 = m * g; // Tension at the start - T = mg

    // Tension at theta = 45 degrees
    const theta = 45 * (Math.PI / 180); // converting to radians
    const v_squared = 2 * r * g * (Math.sin(theta) - Math.sin(0)); // v^2 = 2rg(sin(theta) - sin(0))
    const T45 = m * math.sin(theta) * g + (m * v_squared / r); // T = mg*sin(theta) + mv^2/r

    return {
        params: {
            m: m,
            r: r,
            g: g
        },
        correct_answers: {
            T_initial: T0,
            T_theta45: T45
        },
        nDigits: 3,
        sigfigs: 3
    };
}

module.exports = { generate };

