const math = require('mathjs');

const generate = () => {
    const mass = 0.2; // kg
    const speed = 0.5; // m/s
    const g = 9.81; // m/s² (acceleration due to gravity)
    const r = 0.2 * Math.sin(Math.atan(0.8)); // Based on the cone's geometry and relationships 

    // Calculate tension T
    const T = (mass * speed ** 2) / r;  

    // Calculate normal reaction N
    const N = (mass * g + T * Math.sin(Math.atan(0.8))) / Math.cos(Math.atan(0.8));  

    // Prepare result data
    const data = {
        params: {
            mass: mass,
            speed: speed,
            g: g,
            r: r,
        },
        correct_answers: {
            T: math.round(T, 3), // Tension to 3 significant figures
            N: math.round(N, 3)  // Normal force to 3 significant figures
        },
        nDigits: 3,
        sigfigs: 3
    };

    console.log(data);
    return data;
}

module.exports = {
    generate
};

