const math = require('mathjs');

const generate = () => {
    // Constants
    const r_c = 0.4; // ft
    const g = 32.2; // ft/s^2, acceleration due to gravity
    const W = 0.5 * g; // 0.5 lb weight of the ball
    const theta_deg = 30; // degrees
    const theta = math.unit(theta_deg, 'degrees').toNumber('radians'); // convert to radians

    // Angular velocity and acceleration inputs at the instant
    const omega = math.randomInt(1, 5); // assume a random angular velocity in rad/s
    const alpha = math.randomInt(1, 5); // assume a random angular acceleration in rad/s^2

    // Calculate radius based on theta
    const r = 2 * r_c * math.cos(theta);

    // Calculate derivatives
    const dr_dt = -2 * r_c * math.sin(theta) * omega;
    const d2r_dt2 = -2 * r_c * math.cos(theta) * omega * omega + (-2 * r_c * math.sin(theta) * alpha);

    // Mass of the ball (constant for a 0.5 lb ball)
    const m = W / g;

    // Forces in r direction
    const N = (m * (d2r_dt2 - r * omega * omega) + W * math.sin(theta)) / math.cos(theta);

    // Forces in theta direction
    const F_OA = (m * (r * alpha + 2 * dr_dt * omega) + W * math.cos(theta) - N * math.sin(theta));

    // Return parameters and correct answers
    const data = {
        params: {
            W: W,
            theta_deg: theta_deg,
            r: r,
            unitsForce: 'lb',
            unitsDist: 'ft'
        },
        correct_answers: {
            N: N,
            F_OA: F_OA,
        },
        nDigits: 3,
        sigfigs: 3
    };

    console.log(data);
    return data;
};

